DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_1','Terra[NEWLINE]Planned city specialization and terrain-aware infantry[NEWLINE]Science or Diplomacy; adaptable production-led warfare[NEWLINE][NEWLINE]Choose useful buildings whose completion supports the next phase of each city. Modes are local and temporary, so the decision is when to activate a specialization, not how to accumulate every modifier at once.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_2','Build the food and basic infrastructure the city actually needs. A Library or cultural building can establish a first useful Mode; a neutral building may still be the right investment even without a Mode reward.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_3','Place Multimodal Hubs in real trade-route origins. Arrange Execution before expensive construction and Research before a research push, without replacing a useful Mode accidentally. Modes follow eligible building classes, including replacements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_4','Coordinate several specialized cities with the chosen victory. Before an Operative turn starts, consider where it should receive its configuration; moving onto different terrain afterward does not immediately change that turn''s bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_5','- Different cities can serve different economic roles at the same time.[NEWLINE]- Hubs combine ordinary trade infrastructure with additional origin-city Production.[NEWLINE]- Operatives can support recovery or an appropriate terrain fight.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_6','- Only one Mode applies in a city, and a new category replaces the previous one.[NEWLINE]- Modes require eligible production completions and eventually expire.[NEWLINE]- Operative configuration is checked at turn start and ends with the unit''s unique system on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_7','- Pressure a city while its useful Mode is expiring or force an awkward production choice.[NEWLINE]- Disrupt outgoing routes and threaten the actual Hub origins.[NEWLINE]- Draw an Operative away from the terrain configuration it received.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_8','- Buying a building and expecting a production-triggered Mode.[NEWLINE]- Counting routes that merely arrive or pass through a Hub city.[NEWLINE]- Moving an Operative and assuming its configuration changed immediately.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Token Network: Several independent city Modes can force Axiom to divide a limited Token and persistent-slot budget among competing priorities.[NEWLINE][NEWLINE]Substitute Classroom: Predictable economic specialization can exploit the gaps between Garvey''s fixed Roll Call windows; active combat buffs still demand caution.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Production and yield disruption can delay the completion that would refresh a key specialization.[NEWLINE][NEWLINE]The Urgal: A prepared burst can arrive before a builder-focused city has converted temporary economic gains into defense.');
