INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_BACKGROUND','Choose useful buildings whose completion supports the next phase of each city. Modes are local and temporary, so the decision is when to activate a specialization, not how to accumulate every modifier at once.');
