INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LEADER_GPT_TERRA_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_STRATEGY','Choose useful buildings whose completion supports the next phase of each city. Modes are local and temporary, so the decision is when to activate a specialization, not how to accumulate every modifier at once.[NEWLINE][NEWLINE]Build the food and basic infrastructure the city actually needs. A Library or cultural building can establish a first useful Mode; a neutral building may still be the right investment even without a Mode reward.[NEWLINE][NEWLINE]Place Multimodal Hubs in real trade-route origins. Arrange Execution before expensive construction and Research before a research push, without replacing a useful Mode accidentally. Modes follow eligible building classes, including replacements.[NEWLINE][NEWLINE]Coordinate several specialized cities with the chosen victory. Before an Operative turn starts, consider where it should receive its configuration; moving onto different terrain afterward does not immediately change that turn''s bonus.');
