INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_LEADER_TEXT_2','Build the food and basic infrastructure the city actually needs. A Library or cultural building can establish a first useful Mode; a neutral building may still be the right investment even without a Mode reward.[NEWLINE][NEWLINE]Place Multimodal Hubs in real trade-route origins. Arrange Execution before expensive construction and Research before a research push, without replacing a useful Mode accidentally. Modes follow eligible building classes, including replacements.[NEWLINE][NEWLINE]Coordinate several specialized cities with the chosen victory. Before an Operative turn starts, consider where it should receive its configuration; moving onto different terrain afterward does not immediately change that turn''s bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TERRAFRAMEWORK_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Token Network: Several independent city Modes can force Axiom to divide a limited Token and persistent-slot budget among competing priorities.[NEWLINE][NEWLINE]Substitute Classroom: Predictable economic specialization can exploit the gaps between Garvey''s fixed Roll Call windows; active combat buffs still demand caution.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Production and yield disruption can delay the completion that would refresh a key specialization.[NEWLINE][NEWLINE]The Urgal: A prepared burst can arrive before a builder-focused city has converted temporary economic gains into defense.');
